export class LocalStorage implements Storage {
  async put(key, body) {
    const full = path.join('{{root}}', key);
    await fs.promises.mkdir(path.dirname(full), { recursive: true });
    if (Buffer.isBuffer(body)) await fs.promises.writeFile(full, body);
    else await pipeline(body, fs.createWriteStream(full));
  }
  async get(key) { return fs.createReadStream(path.join('{{root}}', key)); }
  async delete(key) { await fs.promises.unlink(path.join('{{root}}', key)); }
  async url(key) { return `/files/${encodeURIComponent(key)}`; }
}
